<section class="panel chart-panel"><h2>Reservations by status</h2><div class="chart-area"><canvas id="reservationStatusChart"></canvas></div></section>
<section class="panel"><form class="filter-form" method="get"><label>Search by name or email<input name="search" value="<?= e($search) ?>" placeholder="Customer name or email"></label><label>Filter by status<select name="status"><option value="">All statuses</option><?php foreach (['pending','confirmed','rejected','cancelled'] as $item): ?><option value="<?= e($item) ?>" <?= $status === $item ? 'selected' : '' ?>><?= e(ucfirst($item)) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit">Apply filters</button><a class="btn btn-outline" href="dashboard.php">Clear</a></form>
