<script>window.addEventListener('DOMContentLoaded',function(){if(!window.Chart)return;new Chart(document.getElementById('reservationStatusChart'),{type:'bar',data:{labels:['Pending','Confirmed','Rejected','Cancelled'],datasets:[{label:'Reservations',data:[<?= (int)$stats['pending'] ?>,<?= (int)$stats['confirmed'] ?>,<?= (int)$stats['rejected'] ?>,<?= (int)$stats['cancelled'] ?>],backgroundColor:['#d99a17','#16834a','#d34b4b','#8993a2'],borderRadius:8,maxBarThickness:64}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});});</script></body></html>
